#!/usr/bin/env bash
# 福彩门店内容流水线 · 一键安装（macOS / Linux）
# 用法：curl -fsSL <raw脚本地址> | bash
set -euo pipefail
PAYLOAD=""
SKILL="fucai-store-content-pipeline"

echo
echo "福彩门店内容流水线 · 一键安装"
echo "---------------------------------------------"

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
printf '%s' "$PAYLOAD" | (base64 --decode 2>/dev/null || base64 -D) > "$tmp/skill.zip"
unzip -q "$tmp/skill.zip" -d "$tmp"

src="$tmp/$SKILL"
if [ ! -d "$src" ]; then
  echo "[错误] 解包后找不到技能文件夹。" >&2
  exit 1
fi

targets=()
for base in "$HOME/Library/Application Support/Doubao" "$HOME/.config/Doubao" "$HOME/Doubao"; do
  if [ -d "$base" ]; then
    while IFS= read -r d; do targets+=("$d"); done < <(find "$base" -maxdepth 5 -type d -name ".user_skills" 2>/dev/null)
  fi
done
if [ -d "$HOME/Doubao/skills" ]; then targets+=("$HOME/Doubao/skills"); fi

if [ ${#targets[@]} -eq 0 ]; then
  echo "[未找到] 没定位到豆包的技能目录，请手动安装："
  echo "  把 fucai-store-content-pipeline 文件夹放到"
  echo "  ~/Library/Application Support/Doubao/User Data/Default/.doubao/agent_mode/workspace/.user_skills/"
  echo "  然后重启豆包。"
  exit 0
fi

for t in "${targets[@]}"; do
  dst="$t/$SKILL"
  if [ -d "$dst" ]; then
    bak="${dst}.bak_$(date +%Y%m%d%H%M%S)"
    mv "$dst" "$bak"
    echo "[备份] 发现旧版本，已改名为 $(basename "$bak")"
  fi
  cp -R "$src" "$dst"
  echo "[完成] 已安装到 $t"
done

echo
echo "重启豆包后生效。用法：在对话里发「主题：门店便民」"
